-- F2M1 SHOP SUPABASE SETUP
-- Run once in Supabase SQL Editor. After registering admin, see final instructions.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text,display_name text,is_admin boolean not null default false,created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text,unit_size int not null default 300 check(unit_size>0),price_per_unit bigint not null check(price_per_unit>0),min_quantity int not null default 300 check(min_quantity>0),active boolean not null default true,created_at timestamptz default now());
create table if not exists public.wallets(user_id uuid primary key references public.profiles(id) on delete cascade,balance bigint not null default 0 check(balance>=0),updated_at timestamptz default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),product_id uuid references public.products(id),order_code text unique not null,roblox_username text not null,quantity int not null check(quantity>0),unit_size int not null,unit_price bigint not null,total_price bigint not null check(total_price>0),status text not null default 'awaiting_payment' check(status in('awaiting_payment','payment_submitted','payment_verified','processing','completed','payment_rejected','cancelled')),admin_note text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.payment_proofs(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,user_id uuid not null references public.profiles(id),storage_path text unique not null,file_name text not null,mime_type text not null,file_size bigint not null,created_at timestamptz default now());
create table if not exists public.topups(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),topup_code text unique not null,amount bigint not null check(amount>=1000),status text not null default 'pending' check(status in('pending','approved','rejected')),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,created_at timestamptz default now());
create table if not exists public.wallet_transactions(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),amount bigint not null,transaction_type text not null,description text,reference_id uuid,created_at timestamptz default now());
create table if not exists public.order_logs(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,actor_id uuid references public.profiles(id),old_status text,new_status text not null,note text,created_at timestamptz default now());
create table if not exists public.store_settings(key text primary key,value text,updated_at timestamptz default now());
insert into public.products(slug,name,description,unit_size,price_per_unit,min_quantity) values('roblox-followers','Roblox Followers','Followers Roblox',300,5000,300) on conflict(slug) do nothing;
insert into public.store_settings(key,value) values('qris_label','QRIS F2M1 SHOP'),('followers_price_per_unit','5000'),('followers_min_quantity','300') on conflict(key) do nothing;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and is_admin);$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,email) values(new.id,new.email) on conflict do nothing;insert into public.wallets(user_id) values(new.id) on conflict do nothing;return new;end;$$;
drop trigger if exists f2m1_new_user on auth.users;
create trigger f2m1_new_user after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.create_order(p_product_id uuid,p_roblox_username text,p_quantity int) returns public.orders language plpgsql security definer set search_path=public as $$
declare p public.products%rowtype;o public.orders%rowtype;v_total bigint;
begin if auth.uid() is null then raise exception 'Login diperlukan';end if;
if length(trim(coalesce(p_roblox_username,'')))<3 then raise exception 'Username tidak valid';end if;
select * into p from public.products where id=p_product_id and active=true;if not found then raise exception 'Produk tidak tersedia';end if;
if p_quantity<p.min_quantity or p_quantity%p.unit_size<>0 then raise exception 'Jumlah harus minimal % dan kelipatan %',p.min_quantity,p.unit_size;end if;
v_total=(p_quantity/p.unit_size)*p.price_per_unit;
insert into public.orders(user_id,product_id,order_code,roblox_username,quantity,unit_size,unit_price,total_price) values(auth.uid(),p.id,'F2M1-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,9)),trim(p_roblox_username),p_quantity,p.unit_size,p.price_per_unit,v_total) returning * into o;
insert into public.order_logs(order_id,actor_id,new_status,note) values(o.id,auth.uid(),'awaiting_payment','Order dibuat');return o;end;$$;
create or replace function public.submit_payment_proof(p_order_id uuid,p_storage_path text,p_file_name text,p_mime_type text,p_file_size bigint) returns uuid language plpgsql security definer set search_path=public,storage as $$
declare o public.orders%rowtype;v_id uuid;
begin select * into o from public.orders where id=p_order_id and user_id=auth.uid() for update;if not found then raise exception 'Order tidak ditemukan';end if;
if o.status not in('awaiting_payment','payment_rejected') then raise exception 'Order tidak menerima bukti baru';end if;
if p_file_size<1 or p_file_size>5242880 then raise exception 'Maksimal 5MB';end if;
if p_mime_type not in('image/jpeg','image/png','application/pdf') then raise exception 'Format tidak didukung';end if;
if p_storage_path not like 'proofs/'||auth.uid()::text||'/'||p_order_id::text||'/%' then raise exception 'Path tidak valid';end if;
if not exists(select 1 from storage.objects where bucket_id='payment-proofs' and name=p_storage_path) then raise exception 'Objek file belum terunggah';end if;
insert into public.payment_proofs(order_id,user_id,storage_path,file_name,mime_type,file_size) values(p_order_id,auth.uid(),p_storage_path,p_file_name,p_mime_type,p_file_size) returning id into v_id;
update public.orders set status='payment_submitted',updated_at=now() where id=p_order_id;
insert into public.order_logs(order_id,actor_id,old_status,new_status,note) values(o.id,auth.uid(),o.status,'payment_submitted','Bukti pembayaran dikirim');return v_id;end;$$;
create or replace function public.create_topup(p_amount bigint) returns public.topups language plpgsql security definer set search_path=public as $$declare t public.topups%rowtype;begin if auth.uid() is null then raise exception 'Login diperlukan';end if;if p_amount<1000 or p_amount>10000000 then raise exception 'Nominal tidak valid';end if;insert into public.topups(user_id,topup_code,amount) values(auth.uid(),'DEP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,9)),p_amount) returning * into t;return t;end;$$;
create or replace function public.admin_update_order_status(p_order_id uuid,p_status text,p_note text default null) returns void language plpgsql security definer set search_path=public as $$declare o public.orders%rowtype;begin if not public.is_admin() then raise exception 'Admin only';end if;if p_status not in('payment_verified','processing','completed','payment_rejected','cancelled') then raise exception 'Status invalid';end if;select * into o from public.orders where id=p_order_id for update;if not found then raise exception 'Order not found';end if;update public.orders set status=p_status,admin_note=p_note,updated_at=now() where id=p_order_id;insert into public.order_logs(order_id,actor_id,old_status,new_status,note) values(o.id,auth.uid(),o.status,p_status,p_note);end;$$;
create or replace function public.admin_review_topup(p_topup_id uuid,p_approve boolean) returns void language plpgsql security definer set search_path=public as $$declare t public.topups%rowtype;begin if not public.is_admin() then raise exception 'Admin only';end if;select * into t from public.topups where id=p_topup_id for update;if not found or t.status<>'pending' then raise exception 'Deposit tidak tersedia';end if;update public.topups set status=case when p_approve then 'approved' else 'rejected' end,reviewed_by=auth.uid(),reviewed_at=now() where id=t.id;if p_approve then insert into public.wallets(user_id,balance) values(t.user_id,t.amount) on conflict(user_id) do update set balance=public.wallets.balance+excluded.balance,updated_at=now();insert into public.wallet_transactions(user_id,amount,transaction_type,description,reference_id) values(t.user_id,t.amount,'deposit','Deposit disetujui '||t.topup_code,t.id);end if;end;$$;
alter table public.profiles enable row level security;alter table public.products enable row level security;alter table public.wallets enable row level security;alter table public.orders enable row level security;alter table public.payment_proofs enable row level security;alter table public.topups enable row level security;alter table public.wallet_transactions enable row level security;alter table public.order_logs enable row level security;alter table public.store_settings enable row level security;
create policy profile_self_admin on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());
create policy profile_update_self on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy products_read on public.products for select to anon,authenticated using(active or public.is_admin());
create policy products_admin on public.products for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy wallets_self_admin on public.wallets for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy orders_self_admin on public.orders for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy proofs_self_admin on public.payment_proofs for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy topups_self_admin on public.topups for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy wallet_tx_self_admin on public.wallet_transactions for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy logs_self_admin on public.order_logs for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and (o.user_id=auth.uid() or public.is_admin())));
create policy settings_read on public.store_settings for select to authenticated using(key in('qris_path','qris_label','followers_price_per_unit','followers_min_quantity') or public.is_admin());
create policy settings_admin on public.store_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
revoke insert,update,delete on public.profiles,public.wallets,public.orders,public.payment_proofs,public.topups,public.wallet_transactions,public.order_logs from anon,authenticated;
grant select on public.profiles,public.wallets,public.orders,public.payment_proofs,public.topups,public.wallet_transactions,public.order_logs,public.store_settings to authenticated;
grant update(display_name) on public.profiles to authenticated;grant select on public.products to anon,authenticated;grant update(price_per_unit,min_quantity,active,name,description) on public.products to authenticated;grant insert,update on public.store_settings to authenticated;
grant execute on function public.create_order(uuid,text,int) to authenticated;grant execute on function public.submit_payment_proof(uuid,text,text,text,bigint) to authenticated;grant execute on function public.create_topup(bigint) to authenticated;grant execute on function public.admin_update_order_status(uuid,text,text) to authenticated;grant execute on function public.admin_review_topup(uuid,boolean) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('payment-proofs','payment-proofs',false,5242880,array['image/jpeg','image/png','application/pdf']) on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('store-assets','store-assets',false,5242880,array['image/jpeg','image/png']) on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types;
create policy proof_upload_own on storage.objects for insert to authenticated with check(bucket_id='payment-proofs' and (storage.foldername(name))[1]='proofs' and (storage.foldername(name))[2]=auth.uid()::text);
create policy proof_read_own_admin on storage.objects for select to authenticated using(bucket_id='payment-proofs' and ((storage.foldername(name))[2]=auth.uid()::text or public.is_admin()));
create policy qris_read_auth on storage.objects for select to authenticated using(bucket_id='store-assets' and (storage.foldername(name))[1]='qris');
create policy qris_upload_admin on storage.objects for insert to authenticated with check(bucket_id='store-assets' and public.is_admin() and (storage.foldername(name))[1]='qris');
-- Register admin in app, then run: update public.profiles set is_admin=true where email='EMAIL_ADMIN_KAMU';
